begin;
create temporary table phase1_extra_results(code text) on commit drop;
do $$ declare o uuid:='10000000-0000-4000-8000-000000000001'; x uuid:=gen_random_uuid(); a uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); advocate uuid:=gen_random_uuid(); p uuid:=gen_random_uuid(); q uuid:=gen_random_uuid(); c uuid:=gen_random_uuid(); d uuid:=gen_random_uuid(); t record; n integer; denied boolean; begin
insert into public.orgs(id,org_id,code,name) values(x,x,'rollback_other_org','Fictional other organization');
insert into public.accounts(id,org_id,kind) values(a,o,'patient'),(b,x,'patient'),(advocate,o,'advocate');
insert into public.patients(id,org_id,account_id,source_key,first_name,last_name,synthetic) values(p,o,a,'rollback_extra_a','Fictional','Alpha',true),(q,x,b,'rollback_extra_b','Fictional','Beta',true);
insert into public.consent_records(id,org_id,patient_id,consent_type,recipients,purpose_code,status,effective_at,signed_by_kind,signature_method,signed_at,synthetic) values(c,o,p,'telehealth','[{"kind":"org","name":"Fictional program","directoryRef":"fictional-program"}]','treatment','active',now(),'patient','e_sign',now(),true),(d,x,q,'telehealth','[{"kind":"org","name":"Fictional program","directoryRef":"fictional-program"}]','treatment','active',now(),'patient','e_sign',now(),true);
insert into public.consent_signed_copies(org_id,consent_record_id,storage_pointer,sha256,synthetic) values(o,c,'consent-signed/'||o::text||'/'||c::text||'/synthetic.pdf',repeat('a',64),true),(x,d,'consent-signed/'||x::text||'/'||d::text||'/synthetic.pdf',repeat('b',64),true);
execute format('create or replace function app.account_id() returns uuid language sql stable security definer set search_path='''' as %L','select '||quote_literal(a::text)||'::uuid');
execute 'set local role authenticated'; select count(*) into n from public.consent_records; execute 'reset role'; if n<>1 then raise exception 'consent_owner_scope'; end if; insert into phase1_extra_results values('consent_own_cross_org');
execute 'set local role authenticated'; select count(*) into n from public.consent_signed_copies; execute 'reset role'; if n<>1 then raise exception 'copy_owner_scope'; end if; insert into phase1_extra_results values('copy_own_cross_org');
if exists(select 1 from app.can_access('demographics',q) where level<>'none') then raise exception 'cross_org_helper'; end if; insert into phase1_extra_results values('cross_org_helper_denied');
execute format('create or replace function app.account_id() returns uuid language sql stable security definer set search_path='''' as %L','select '||quote_literal(advocate::text)||'::uuid');
execute 'set local role authenticated'; select count(*) into n from public.patients; execute 'reset role'; if n<>0 then raise exception 'advocate_patient_leak'; end if; insert into phase1_extra_results values('advocate_patient_denied');
execute 'set local role authenticated'; select count(*) into n from public.consent_records; execute 'reset role'; if n<>0 then raise exception 'advocate_consent_leak'; end if; insert into phase1_extra_results values('advocate_consent_denied');
for t in select schemaname,tablename from pg_tables where schemaname in ('public','app') loop denied:=false; begin execute 'set local role anon'; execute format('select count(*) from %I.%I',t.schemaname,t.tablename) into n; exception when insufficient_privilege then denied:=true; end; execute 'reset role'; if not denied then raise exception 'anonymous_access %',t.tablename; end if; insert into phase1_extra_results values('anon_'||t.tablename); end loop;
denied:=false; begin delete from public.consent_signed_copies where consent_record_id=c; exception when raise_exception then denied:=true; end; if not denied then raise exception 'copy_delete'; end if; insert into phase1_extra_results values('copy_no_delete');
denied:=false; begin update public.consent_signed_copies set storage_pointer='other' where consent_record_id=c; exception when raise_exception then denied:=true; end; if not denied then raise exception 'copy_update'; end if; insert into phase1_extra_results values('copy_immutable');
end $$;
do $$ declare o uuid:='10000000-0000-4000-8000-000000000001'; a uuid:=gen_random_uuid(); m uuid:=gen_random_uuid(); denied boolean; before_n int; begin
insert into public.accounts(id,org_id,kind) values(a,o,'staff'); insert into public.staff_members(id,org_id,account_id,source_key,name) values(m,o,a,'rollback_flag_staff','Fictional flag staff'); insert into public.staff_role_assignments(org_id,staff_member_id,role,is_primary) values(o,m,'sys_admin',true),(o,m,'intake_coordinator',false);
execute format('create or replace function app.account_id() returns uuid language sql stable security definer set search_path='''' as %L','select '||quote_literal(a::text)||'::uuid'); perform app.set_acting_role('sys_admin');
denied:=false; begin perform app.set_feature_flag('hie_simulated','live','test'); exception when raise_exception then denied:=true; end; if not denied then raise exception 'simulated_live'; end if; insert into phase1_extra_results values('simulated_never_live');
denied:=false; begin perform app.set_feature_flag('persist_accounts','on',null); exception when raise_exception then denied:=true; end; if not denied then raise exception 'reason_missing'; end if; insert into phase1_extra_results values('flag_reason_required');
select count(*) into before_n from public.audit_events where actor_account_id=a and action_code='feature_flag.changed'; perform app.set_feature_flag('persist_accounts','on','test'); if (select count(*) from public.audit_events where actor_account_id=a and action_code='feature_flag.changed')<>before_n+1 then raise exception 'flag_audit_count'; end if; insert into phase1_extra_results values('flag_one_audit');
perform app.set_acting_role('intake_coordinator'); denied:=false; begin perform app.set_feature_flag('persist_accounts','off','test'); exception when raise_exception then denied:=true; end; if not denied then raise exception 'role_union'; end if; insert into phase1_extra_results values('flag_held_admin_no_union');
end $$;
select count(*) checks from phase1_extra_results;
rollback;